// Abre en el navegador el visor del acta de la IA de un issue: make visor-acta ISSUE=54
//
// El acta (ADR-0006 del monorepo) vive en .ia/registros/<issue>/ y su visor lo genera el plugin
// sdlc-ia (acta/visor-acta.mjs). Este script solo junta las piezas para que verla sea un comando:
//
// 1. Ubica la carpeta acta/ del plugin. SDLC_IA_ACTA la fija a mano; si no, la pregunta a
//    `claude plugin list --json`, que dice desde donde carga el plugin de verdad (readFromFolder
//    cuando se instalo desde una carpeta, installPath si no).
// 2. Toma la curada mas reciente del issue. Con --verificar re-ejecuta antes la sesion sin la IA
//    (necesita Docker) y deja el reporte junto al acta; sin reporte, el visor dice "registrada,
//    sin verificar" en vez de afirmar lo que nadie comprobo.
// 3. Escribe el HTML en .ia/visor/<issue>.html, que no se versiona, y lo abre.
//
// Sin dependencias npm; corre con node >= 18 en Windows, macOS y Linux.
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync, spawnSync } from 'node:child_process';

const [issue, ...opciones] = process.argv.slice(2);
const verificar = opciones.includes('--verificar');

function abortar(...lineas) {
  console.error(lineas.join('\n'));
  process.exit(1);
}

if (!/^\d+$/.test(issue || '')) abortar('Uso: make visor-acta ISSUE=<numero> [VERIFICAR=1]');

function carpetaDelActa() {
  if (process.env.SDLC_IA_ACTA) return process.env.SDLC_IA_ACTA;
  let lista;
  try {
    // shell: true para que Windows encuentre claude.cmd igual que en una terminal.
    lista = JSON.parse(execFileSync('claude plugin list --json', { encoding: 'utf8', shell: true }));
  } catch {
    abortar('No pude preguntarle a Claude Code donde esta el plugin sdlc-ia.',
      'Fija la carpeta a mano: SDLC_IA_ACTA=<ruta>/sdlc-ia/acta make visor-acta ISSUE=' + issue);
  }
  const plugin = lista.find((p) => /^sdlc-ia@/.test(p.id));
  if (!plugin) abortar('El plugin sdlc-ia no esta instalado en este Claude Code.');
  return path.join(plugin.readFromFolder || plugin.installPath, 'acta');
}

const carpeta = path.join('.ia', 'registros', issue);
const curadas = fs.existsSync(carpeta)
  ? fs.readdirSync(carpeta).filter((f) => f.endsWith('.acta.curada.jsonl'))
    .map((f) => path.join(carpeta, f))
    .sort((a, b) => fs.statSync(b).mtimeMs - fs.statSync(a).mtimeMs)
  : [];
if (!curadas.length) {
  abortar(`El issue #${issue} no tiene acta en ${carpeta}.`,
    'Se escribe al registrar la sesion (registrar-sesion.mjs) y llega con la PR que la cita.');
}
const curada = curadas[0];
if (curadas.length > 1) console.log(`El issue tiene ${curadas.length} actas; abro la mas reciente.`);

const acta = carpetaDelActa();
const correr = (script, args) => {
  const r = spawnSync(process.execPath, [path.join(acta, script), ...args], { stdio: 'inherit' });
  if (r.status !== 0) abortar(`${script} termino con codigo ${r.status}.`);
};

const reporte = curada.replace(/\.acta\.curada\.jsonl$/, '.acta.reporte.json');
if (verificar) correr('reejecutar-acta.mjs', [curada, '--reporte', reporte]);

fs.mkdirSync(path.join('.ia', 'visor'), { recursive: true });
const salida = path.join('.ia', 'visor', `${issue}.html`);
correr('visor-acta.mjs',
  [curada, ...(fs.existsSync(reporte) ? ['--reporte', reporte] : []), '--salida', salida]);

const html = path.resolve(salida);
const [abrir, ...args] = process.platform === 'win32' ? ['cmd', '/c', 'start', '""', html]
  : process.platform === 'darwin' ? ['open', html] : ['xdg-open', html];
spawnSync(abrir, args, { stdio: 'ignore', shell: process.platform === 'win32' });
console.log(`Visor del acta del issue #${issue}: ${html}`);

